const regions=[['THE FORGOTTEN TEMPLE','Moderate','A sunken sanctuary surrounding the first known signal.'],['THE ABYSSAL ARCHIVE','Severe','A drowned repository beneath a lightless planetary sea.'],['THE ASHEN CITY','High','A glass-black metropolis preserved beneath metallic ash.'],['THE CELESTIAL RUINS','Extreme','Orbital monuments adrift above a fractured world.'],['THE OBSIDIAN VAULT','Unknown','A sealed chamber older than every recovered record.']];
const civs=[['NEXUS','Origin unverified'],['VESPERA','Celestial frontier'],['KHEM-RA','Ashen inner world'],['THALASS','Abyssal continuum'],['THE FIRST ONES','Record sealed']];
let account=null,selectedRegion=null,authenticated=false,regionsFromApi=[];
const API=(window.RELIC_ZERO_API_BASE||'').replace(/\/$/,'');
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function short(a){return a?`${a.slice(0,6)}…${a.slice(-4)}`:'Connect Wallet'}
function route(){const id=(location.hash||'#home').slice(1);const target=document.getElementById(id)||$('#home');$$('.view').forEach(v=>v.classList.toggle('active',v===target));$$('.links a').forEach(a=>a.classList.toggle('active',a.hash===`#${target.id}`));$('#walletMenu').classList.remove('show');scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
addEventListener('hashchange',route);route();
$('.menu-btn').onclick=()=>$('.links').classList.toggle('open');$$('.links a').forEach(a=>a.onclick=()=>$('.links').classList.remove('open'));
$('#trailerBtn').onclick=()=>toast('Trailer coming soon — no video has been published.');
$('#regionGrid').innerHTML=regions.map((r,i)=>`<article class="region" data-i="${i}"><label>REGION 0${i+1}</label><h3>${r[0]}</h3><p>${r[2]}</p><small>DIFFICULTY · ${r[1]}<br>PROGRESS · UNAVAILABLE</small></article>`).join('');
$('#civilizations').innerHTML=civs.map((c,i)=>`<article class="civilization"><i>0${i+1}</i><h2>${c[0]}</h2><p>${c[1]}. Additional records unlock through verified related discoveries.</p><small>PROGRESS · UNAVAILABLE</small></article>`).join('');
$$('.region').forEach(el=>el.onclick=()=>{selectedRegion=regions[+el.dataset.i];$$('.region').forEach(x=>x.classList.toggle('selected',x===el));$('#expeditionTitle').textContent=selectedRegion[0];$('#expeditionStatus').textContent=account?'Region selected. Production expedition service is not configured in this preview.':'Connect an injected EIP-1193 wallet to continue.';$('#expeditionBtn').disabled=!account});
async function api(path,options={}){if(!API)throw new Error('BACKEND_UNAVAILABLE');const r=await fetch(`${API}${path}`,{credentials:'include',headers:{'content-type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||`HTTP_${r.status}`);return data}
async function authenticate(){if(!account||!window.ethereum)throw new Error('WALLET_REQUIRED');const n=await api('/api/auth/nonce',{method:'POST',body:JSON.stringify({walletAddress:account})});const chainHex=await ethereum.request({method:'eth_chainId'}),chainId=parseInt(chainHex,16),issuedAt=new Date(),expiration=new Date(Date.now()+5*60_000);const message=`${n.domain} wants you to sign in with your Ethereum account:\n${account}\n\nSign in to RELIC ZERO.\n\nURI: ${location.origin}\nVersion: 1\nChain ID: ${chainId}\nNonce: ${n.nonce}\nIssued At: ${issuedAt.toISOString()}\nExpiration Time: ${expiration.toISOString()}`;const signature=await ethereum.request({method:'personal_sign',params:[message,account]});await api('/api/auth/verify',{method:'POST',body:JSON.stringify({message,signature})});authenticated=true;toast('Wallet authenticated securely.');return true}
$('#expeditionBtn').onclick=async()=>{if(!selectedRegion)return;const b=$('#expeditionBtn');b.disabled=true;b.textContent='VALIDATING…';try{if(!authenticated)await authenticate();const region=regionsFromApi.find(r=>r.name===selectedRegion[0]);if(!region)throw new Error('REGION_DATA_UNAVAILABLE');const key=crypto.randomUUID();const e=await api('/api/expeditions',{method:'POST',body:JSON.stringify({regionId:region.id,idempotencyKey:key})});$('#expeditionStatus').textContent=`Expedition ${e.status.toLowerCase()}. Generation continues safely in the durable queue.`;toast('Expedition accepted. You may leave and return.');pollExpedition(e.id)}catch(e){$('#expeditionStatus').textContent=e.message==='BACKEND_UNAVAILABLE'?'Backend not configured for this deployment.':'Expedition failed: '+e.message;toast($('#expeditionStatus').textContent)}finally{b.textContent='START EXPEDITION';b.disabled=!(account&&selectedRegion)}};
async function pollExpedition(id){if(!API)return;const check=async()=>{try{const e=await api(`/api/expeditions/${id}`);$('#expeditionStatus').textContent=e.status==='COMPLETED'?`Discovery complete: ${e.relic?.name||'relic recorded'}.`:e.status==='FAILED'?`Expedition preserved with error: ${e.errorCode||'generation failed'}.`:`Expedition ${e.status.toLowerCase()}.`;if(!['COMPLETED','FAILED'].includes(e.status))setTimeout(check,4000)}catch(err){$('#expeditionStatus').textContent='Status temporarily unavailable. Safe to retry.'}};check()}
async function connect(){if(account){$('#walletMenu').classList.toggle('show');return}if(!window.ethereum){toast('No EIP-1193 wallet detected. Install MetaMask, Rabby, or another compatible wallet.');return}try{const [a]=await ethereum.request({method:'eth_requestAccounts'});account=a;renderWallet();toast('Wallet connected. Sign-in remains required for persistent progress.')}catch(e){toast(e.code===4001?'Connection cancelled.':'Wallet connection failed.')}}
function renderWallet(){const label=short(account);$('#walletLabel').textContent=label;$('#walletBtn').classList.toggle('connected',!!account);$('#profileWallet').textContent=account||'NOT CONNECTED';$('#profileChain').textContent=account?'Browser wallet connected · persistent profile service unavailable':'Connect your wallet to load private collection data.';$('#expeditionBtn').disabled=!(account&&selectedRegion)}
$('#walletBtn').onclick=connect;
if(window.ethereum){ethereum.on?.('accountsChanged',a=>{account=a[0]||null;authenticated=false;renderWallet();toast(account?'Active account updated. Please authenticate again.':'Wallet disconnected.');});ethereum.on?.('chainChanged',()=>{authenticated=false;toast('Network changed. Please authenticate again.')})}
$('#walletMenu').onclick=async e=>{const a=e.target.dataset.action;if(!a)return;if(a==='profile')location.hash='profile';if(a==='copy'&&account){await navigator.clipboard.writeText(account);toast('Address copied.')}if(a==='switch')toast('Network configuration must be supplied by the verified backend.');if(a==='disconnect'){try{await api('/api/auth/logout',{method:'POST'})}catch{}account=null;authenticated=false;renderWallet();toast('Authenticated session cleared.')}$('#walletMenu').classList.remove('show')};
$$('#leaderTabs button').forEach(b=>b.onclick=()=>{$$('#leaderTabs button').forEach(x=>x.classList.toggle('active',x===b));toast(`${b.textContent}: no verified records yet.`)});
async function hydrate(){if(!API)return;try{const [stats,liveRegions]=await Promise.all([api('/api/stats'),api('/api/regions')]);regionsFromApi=liveRegions;const values=[stats.explorers,stats.relics,stats.civilizations,stats.archiveRecords];$$('.stats strong').forEach((n,i)=>n.textContent=values[i].toLocaleString());$('.stats p').textContent='LIVE DATABASE';if(stats.featuredRelic){$('.featured h3').textContent=stats.featuredRelic.name;$('.featured p').textContent=stats.featuredRelic.description;const dd=$$('.featured dd');dd[0].textContent=stats.featuredRelic.civilization.name;dd[1].textContent=stats.featuredRelic.category;dd[2].textContent=stats.featuredRelic.rarity;dd[3].textContent=short(stats.featuredRelic.user?.walletAddress)}}catch(e){console.info('RELIC ZERO backend unavailable; preserving explicit empty states.')}}
hydrate();
